# ---- bridges ----
def parallel_bridge(i,j):
    return (hbond(i-1,j) and hbond(j,i+1)) or (hbond(j-1,i) and hbond(i,j+1))
def antiparallel_bridge(i,j):
    return (hbond(i,j) and hbond(j,i)) or (hbond(i-1,j+1) and hbond(j-1,i+1))

bridges = []   # (i, j, type)
for i in range(1, L-1):
    for j in range(i+3, L-1):   # DSSP: j-i > 2
        if parallel_bridge(i,j):  bridges.append((i,j,'P'))
        elif antiparallel_bridge(i,j): bridges.append((i,j,'A'))

# ---- ladders: consecutive bridges ----
bset = {(i,j):t for i,j,t in bridges}
used = set()
ladders = []
for (i,j),t in sorted(bset.items()):
    if (i,j) in used: continue
    lad = [(i,j)]; used.add((i,j))
    a,b = i,j
    while True:
        if t=='P' and (a+1,b+1) in bset and bset[(a+1,b+1)]=='P' and (a+1,b+1) not in used:
            a,b = a+1,b+1
        elif t=='A' and (a+1,b-1) in bset and bset[(a+1,b-1)]=='A' and (a+1,b-1) not in used:
            a,b = a+1,b-1
        else:
            break
        lad.append((a,b)); used.add((a,b))
    ladders.append((lad,t))

sheet_res, bridge_res = set(), set()
for lad,t in ladders:
    tgt = sheet_res if len(lad) > 1 else bridge_res
    for a,b in lad: tgt.add(a); tgt.add(b)
bridge_res -= sheet_res

